"use client";

import { useEffect, useMemo, useState, useTransition } from "react";
import { addCcaCapture, removeCcaCapture } from "./actions";
import { ccaActiveOn, ccaActivities, ccaBands, ccaDayFor, type CcaActivity, type CcaTimeBand } from "../lib/cca-workbook-data";

export type CcaCapture = { id: string; activity_id: string; capture_date: string; created_at: string };
type Photographer = "Jerry" | "Chris";
const target = 2;
const today = new Date().toISOString().slice(0, 10);
const countFor = (activity: CcaActivity, captures: CcaCapture[]) => captures.filter((capture) => capture.activity_id === activity.id && capture.capture_date >= activity.startDate && capture.capture_date <= activity.endDate).length;

export function CcaTodaySummary({ date, captures, onOpen }: { date: string; captures: CcaCapture[]; onOpen: () => void }) {
  const activities = ccaActivities.filter((activity) => ccaActiveOn(activity, date) && activity.status !== "Possibility" && activity.status !== "Cancelled");
  if (!activities.length) return null;
  return <section className="panel cca-summary"><div className="panel-header"><div><strong>Athletics and CCA today</strong><div className="muted">{ccaDayFor(date)} · {activities.length} scheduled records</div></div><button className="secondary" onClick={onOpen}>Plan today's route</button></div>{activities.slice(0, 8).map((activity) => <div className="cca-summary-row" key={activity.id}><div><strong>{activity.name}</strong><div className="class-meta">{activity.program} · {activity.space} · {activity.coaches}</div></div><span className="photo-count">{countFor(activity, captures)}/{target}</span></div>)}</section>;
}

export default function CcaDashboard({ date: initialDate, initialCaptures, onCapturesChange }: { date: string; initialCaptures: CcaCapture[]; onCapturesChange: (captures: CcaCapture[]) => void }) {
  const [date, setDate] = useState(initialDate || today); const [band, setBand] = useState<CcaTimeBand | "all">("all"); const [program, setProgram] = useState("all"); const [category, setCategory] = useState("all"); const [query, setQuery] = useState(""); const [includeReview, setIncludeReview] = useState(true); const [captures, setCaptures] = useState(initialCaptures); const [assignments, setAssignments] = useState<Record<string, Photographer>>({}); const [pending, startTransition] = useTransition();
  useEffect(() => { try { const stored = window.localStorage.getItem("classcapture-cca-route-assignments"); if (stored) setAssignments(JSON.parse(stored) as Record<string, Photographer>); } catch { /* Ignore unavailable browser storage. */ } }, []);
  useEffect(() => { try { window.localStorage.setItem("classcapture-cca-route-assignments", JSON.stringify(assignments)); } catch { /* Ignore unavailable browser storage. */ } }, [assignments]);
  const scheduled = useMemo(() => ccaActivities.filter((activity) => ccaActiveOn(activity, date) && activity.status !== "Possibility" && activity.status !== "Cancelled" && (includeReview || !activity.sourceNote)), [date, includeReview]);
  const activities = scheduled.filter((activity) => (program === "all" || activity.program === program) && (category === "all" || activity.category === category) && (band === "all" || ccaBands(activity, date).includes(band)) && (!query || `${activity.name} ${activity.coaches} ${activity.space} ${activity.program}`.toLowerCase().includes(query.toLowerCase())));
  const assigned = (activity: CcaActivity) => assignments[`${date}:${activity.id}`];
  const assignedCount = (person: Photographer) => Object.entries(assignments).filter(([key, value]) => key.startsWith(`${date}:`) && value === person).length;
  function assign(activity: CcaActivity, person: Photographer) { const key = `${date}:${activity.id}`; setAssignments((old) => { if (old[key] === person) { const next = { ...old }; delete next[key]; return next; } if (assignedCount(person) >= 4) { window.alert(`${person} already has 4 assignments for this day.`); return old; } return { ...old, [key]: person }; }); }
  function update(next: CcaCapture[]) { setCaptures(next); onCapturesChange(next); }
  function add(activity: CcaActivity) { if (!ccaActiveOn(activity, date) || activity.status === "Cancelled" || activity.status === "Possibility" || captures.some((capture) => capture.activity_id === activity.id && capture.capture_date === date)) return; startTransition(async () => { const result = await addCcaCapture(activity.id, date); if (result.capture) update([...captures, result.capture as CcaCapture]); else if (result.error) window.alert(result.error); }); }
  function remove(activity: CcaActivity) { const match = captures.find((capture) => capture.activity_id === activity.id && capture.capture_date === date); if (!match || !window.confirm(`Remove today's visit for ${activity.name}?`)) return; startTransition(async () => { const result = await removeCcaCapture(match.id); if (result.ok) update(captures.filter((capture) => capture.id !== match.id)); else if (result.error) window.alert(result.error); }); }
  const lane = (person: Photographer) => activities.filter((activity) => assigned(activity) === person);
  return <><div className="eyebrow">Daily route planner</div><div className="heading-row"><div><h1>Athletics and CCA</h1><p>{ccaDayFor(date)} · Assign up to four activities to each photographer.</p></div><label className="date-control">Date<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label></div><div className="cca-band-tabs" role="tablist">{([["all", "All"], ["before", "Before school"], ["during", "During school"], ["after", "After school"], ["review", "Needs review"]] as const).map(([value, label]) => <button key={value} className={band === value ? "selected" : ""} onClick={() => setBand(value)}>{label}</button>)}</div><div className="filter-grid cca-filters"><input placeholder="Search activity, coach, location, or program..." value={query} onChange={(event) => setQuery(event.target.value)} /><select value={program} onChange={(event) => setProgram(event.target.value)}><option value="all">All programs</option><option>Activities</option><option>ASIAC</option><option>SAISA</option></select><select value={category} onChange={(event) => setCategory(event.target.value)}><option value="all">All categories</option><option>Athletics</option><option>Activities</option><option>CCA</option></select><label><input type="checkbox" checked={includeReview} onChange={(event) => setIncludeReview(event.target.checked)} /> Include review items</label></div><div className="cca-capacity"><div><strong>Jerry</strong><span>{assignedCount("Jerry")}/4 assigned</span></div><div><strong>Chris</strong><span>{assignedCount("Chris")}/4 assigned</span></div><div><strong>Unassigned</strong><span>{Math.max(activities.length - assignedCount("Jerry") - assignedCount("Chris"), 0)} activities</span></div></div><div className="cca-lanes"><section className="panel cca-lane"><div className="panel-header"><div><strong>Jerry · Photographer 1</strong><div className="muted">{assignedCount("Jerry")}/4 daily limit</div></div></div>{lane("Jerry").length ? lane("Jerry").map((activity) => <div className="cca-lane-item" key={activity.id}><strong>{activity.name}</strong><span>{activity.space} · {activity.timings}</span></div>) : <div className="cca-lane-empty">No activities assigned yet.</div>}</section><section className="panel cca-lane"><div className="panel-header"><div><strong>Chris · Photographer 2</strong><div className="muted">{assignedCount("Chris")}/4 daily limit</div></div></div>{lane("Chris").length ? lane("Chris").map((activity) => <div className="cca-lane-item" key={activity.id}><strong>{activity.name}</strong><span>{activity.space} · {activity.timings}</span></div>) : <div className="cca-lane-empty">No activities assigned yet.</div>}</section></div><div className="panel cca-activity-list"><div className="panel-header"><div><strong>{band === "all" ? "Today's scheduled activities" : band === "before" ? "Before school" : band === "during" ? "During school" : band === "after" ? "After school" : "Needs review"}</strong><div className="muted">{activities.length} shown · select Jerry or Chris to assign</div></div></div>{activities.map((activity) => { const count = countFor(activity, captures); const current = assigned(activity); const countedToday = captures.some((capture) => capture.activity_id === activity.id && capture.capture_date === date); const canAdd = ccaActiveOn(activity, date) && activity.status === "Confirmed"; return <div className="cca-row" key={activity.id}><div className="cca-activity-main"><div className="cca-activity-title"><strong>{activity.name}</strong><span className="cca-category">{activity.program} · {activity.category}</span>{activity.status !== "Confirmed" && <span className="cca-review">{activity.status}</span>}</div><div className="class-meta">{activity.days.join(" · ")} · {activity.timings} · <b>{activity.space}</b> · {activity.coaches}</div>{activity.sourceNote && <div className="cca-review-note">{activity.sourceNote}</div>}<div className="cca-progress"><i style={{ width: `${Math.min(count / target, 1) * 100}%` }} /></div></div><div className="cca-controls"><button className={`cca-assign ${current === "Jerry" ? "selected" : ""}`} onClick={() => assign(activity, "Jerry")} disabled={assignedCount("Jerry") >= 4 && current !== "Jerry"}>Jerry</button><button className={`cca-assign ${current === "Chris" ? "selected" : ""}`} onClick={() => assign(activity, "Chris")} disabled={assignedCount("Chris") >= 4 && current !== "Chris"}>Chris</button><span className="photo-count">{count}/{target}</span><button className="cca-step" aria-label={`Remove visit for ${activity.name}`} disabled={!countedToday || pending} onClick={() => remove(activity)}>−</button><button className="cca-step" aria-label={`Log visit for ${activity.name}`} disabled={!canAdd || countedToday || pending} onClick={() => add(activity)}>+</button></div></div>; })}</div></>;
}
